CREATE TABLE IF NOT EXISTS economic_explainable_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, consensus_id uuid NOT NULL, decision_state text NOT NULL, decision_score numeric(5,2) NOT NULL, confidence text NOT NULL, rationale text NOT NULL, risk_factors jsonb NOT NULL DEFAULT '[]'::jsonb, recommended_actions jsonb NOT NULL DEFAULT '[]'::jsonb, governance_requirements jsonb NOT NULL DEFAULT '[]'::jsonb, source_signal_ids jsonb NOT NULL DEFAULT '[]'::jsonb, auto_execution_allowed boolean NOT NULL DEFAULT false, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_explainable_decision_profile ON economic_explainable_decisions(profile_id,created_at DESC);